plural <- function(n) {
  if (n == 0) return("zero")
  if (n == 1) return("one")
  mod100 <- n %% 100
  if (mod100 == 2 || mod100 == 22 || mod100 == 42 || mod100 == 62 || mod100 == 82) return("two")
  if (mod100 == 3 || mod100 == 23 || mod100 == 43 || mod100 == 63 || mod100 == 83) return("few")
  if (n != 1 && (mod100 == 1 || mod100 == 21 || mod100 == 41 || mod100 == 61 || mod100 == 81)) return("many")
  "other"
}

